function customSpriteRevision(id: string) {
	if (toID(id).startsWith('wishiwashisevii')) return '?v=sevii-shiny-20260925';
	if (id === 'gastrodonaevian' || id === 'gastrodoneastaevian' || id === 'gastrodon-aevian' || id === 'gastrodon-east-aevian') return '?v=gastrodon-aevian-profiles-20260920';
	if (id === 'golisopodaevian' || id === 'golisopodaevianmega' || id === 'golisopod-aevian' || id === 'golisopod-aevian-mega') return '?v=golisopod-aevian-mega-20260920';
	if (id === 'typhlosionmega' || id === 'typhlosion-mega') return '?v=typhlosion-mega-20260920';
	if (id === 'flygonmegaz' || id === 'flygon-megaz') return '?v=flygon-megaz-restored-20260920';
	if (id === 'miloticmega' || id === 'milotic-mega') return '?v=milotic-mega-20260923';
	if (id === 'aurorusmega' || id === 'aurorus-mega') return '?v=aurorus-mega-20260923';
	if (id === 'tyrantrummega' || id === 'tyrantrum-mega') return '?v=tyrantrum-mega-20260923';
	if (id === 'flygonmega' || id === 'flygon-mega') return '?v=flygon-megas-20260920';
	if (id === 'arboliva' || id === 'arbolivamega') return '?v=arboliva-mega-20260919';
	if (id === 'meowscarada') return '?v=meowscarada-icons-20260919';
	if (id === 'clefable' || id === 'clefablemega') return '?v=clefable-icons-20260919';
	if (toID(id).startsWith('toxtricityaevian')) return '?v=toxtricity-aevian-icons-20260918';
	if (id === 'salazzle' || id === 'salazzle-mega') return '?v=salazzle-20260918';
	const spriteid = id.toLowerCase();
	if (spriteid === 'appletun' || spriteid === 'appletun-gmax') return '?v=appletun-back-20260917';
	if (spriteid === 'lilligant') return '?v=lilligant-custom-shiny-1';
	if (spriteid === 'golisopod-mega' || spriteid === 'nidoking-alt') return '?v=sprite-frames-20260915';
	if (['heatran-mega', 'barbaracle-mega', 'zeraora-mega', 'sawsbuck-winter'].includes(spriteid)) return '?v=sprite-audit-20260916';
	if (spriteid === 'banette' || spriteid === 'banette-mega') return '?v=banette-354-2';
	if (spriteid.startsWith('lapras-aevian')) return '?v=lapras-aevian-gmax-1';
	if (spriteid.startsWith('toxtricity-aevian-gmax')) return '?v=toxtricity-aevian-gmax-2';
	if (spriteid.startsWith('froslass-aevian')) return '?v=froslass-aevian-1';
	if (spriteid.startsWith('glalie')) return '?v=glalie-aevian-1';
	if (RESTORED_BW_SHINY_SPRITE_IDS.has(spriteid) || TEAMBUILDER_ONLY_BW_SHINY_SPRITE_IDS.has(spriteid)) {
		return '?v=bw-shiny-restored-1';
	}
	if (toID(id).startsWith('ampharosaevian')) return '?v=ampharos-aevian-1';
 if (toID(id).startsWith('silvally')) return '?v=silvally-forms-20260912';
 if (['aurorus', 'tyrantrum'].includes(toID(id))) return '?v=fossils-20260912';
 if (ROTOM_SHINY_SPRITE_IDS.has(toID(id))) return '?v=rotom-shiny-1';
 if (id === 'tauros' || id.startsWith('taurospaldea')) return '?v=tauros-icons-shiny-1';
 if (id === 'vaporeon' || id === 'flareon') return '?v=vaporeon-flareon-shiny-1';
 if (id === 'espeon' || id === 'umbreon' || id === 'umbreonperfect') return '?v=eeveelution-shiny-refresh-1';
 if (id === 'dragonite' || id === 'dragonitemega') return '?v=dragonite-shiny-refresh-1';
 if (id === 'persian' || id === 'persianalola') return '?v=persian-shiny-refresh-1';
 if (id === 'ninetales' || id === 'ninetalesalola') return '?v=ninetales-icons-20260919';
 if (id === 'nidoking' || id === 'nidoqueen') return '?v=nido-shiny-refresh-1';
 if (id.startsWith('raichu')) return '?v=raichu-gender-refresh-1';
 return ['sharpedo', 'sharpedo-mega', 'sharpedo-megay', 'lopunny', 'lopunny-mega'].includes(id) ? '?v=bw-refresh-2' : '';
}
